// Des: Tests for ru-safe-halt: lowercase fold, judge, stored halt, live lock/captcha/login pages
// Flo: texts > verdict; mock pages > guard result; nothing sent
// I/O: text and html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const halt = @import("ru-safe-halt.zig"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig"); const mock = @import("te-mock-page.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "fold lowers ASCII and Vietnamese capitals" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("tài khoản bị khóa", try halt.lowFold(aren.allocator(), "TÀI KHOẢN BỊ KHÓA")); try T.expectEqualStrings("đăng nhập ở nơi khác", try halt.lowFold(aren.allocator(), "ĐĂNG NHẬP Ở NƠI KHÁC")); try T.expectEqualStrings("ưu tiên", try halt.lowFold(aren.allocator(), "ƯU TIÊN")); try T.expectEqualStrings("abc 123 ✓", try halt.lowFold(aren.allocator(), "AbC 123 ✓")); }
test "fold keeps bad utf8 as is" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("\xff\xfe", try halt.lowFold(aren.allocator(), "\xff\xfe")); }
test "judge finds halt words case-insensitively and names the word" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const cfg: conf.Conf = .{}; const ver = try halt.judge(aren.allocator(), "Hoàn thành CAPTCHA để tiếp tục", cfg.halt_word_list, cfg.labl_qrcd_page); try T.expect(ver.kind == .halt); try T.expectEqualStrings("captcha", ver.word); const ok = try halt.judge(aren.allocator(), "Mom: Dinner at 7?", cfg.halt_word_list, cfg.labl_qrcd_page); try T.expect(ok.kind == .okay); }
test "judge sees the login page before halt words" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const cfg: conf.Conf = .{}; const ver = try halt.judge(aren.allocator(), "ĐĂNG NHẬP TÀI KHOẢN ZALO xác minh", cfg.halt_word_list, cfg.labl_qrcd_page); try T.expect(ver.kind == .login); }
test "empty words and empty label never match" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ver = try halt.judge(aren.allocator(), "anything", &.{""}, ""); try T.expect(ver.kind == .okay); }
test "guardText stores the halt and later clean text still halts" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const cfg: conf.Conf = .{}; var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); try T.expectError(error.Halted, halt.guardText(aren.allocator(), cfg, &sto, 10, "Tài khoản của bạn đã bị khóa tạm thời")); const why = (try sto.haltGet(T.allocator)).?; defer T.allocator.free(why); try T.expectEqualStrings("bị khóa", why); try T.expectError(error.Halted, halt.guardText(aren.allocator(), cfg, &sto, 11, "all fine now")); try sto.haltClear(); try halt.guardText(aren.allocator(), cfg, &sto, 12, "all fine now"); }
test "guardText login page is NeedLogin and does not store a halt" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const cfg: conf.Conf = .{}; var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); try T.expectError(error.NeedLogin, halt.guardText(aren.allocator(), cfg, &sto, 1, "Đăng nhập tài khoản Zalo")); try T.expect((try sto.haltGet(T.allocator)) == null); }
test "M4 live: lock, captcha, elsewhere pages halt, login needs QR, chat is clear" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); const cfg: conf.Conf = .{}; var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); var sto = try data.Stor.open(gpa, ":memory:"); defer sto.close(); try halt.guard(alo, cfg, &sto, mok.conn, 1); try mok.load(fixt.login); try T.expectError(error.NeedLogin, halt.guard(alo, cfg, &sto, mok.conn, 2)); try mok.load(fixt.lock); try T.expectError(error.Halted, halt.guard(alo, cfg, &sto, mok.conn, 3)); try sto.haltClear(); try mok.load(fixt.capt); try T.expectError(error.Halted, halt.guard(alo, cfg, &sto, mok.conn, 4)); try sto.haltClear(); try mok.load(fixt.else_); try T.expectError(error.Halted, halt.guard(alo, cfg, &sto, mok.conn, 5)); try sto.haltClear(); try mok.load(fixt.chat); try halt.guard(alo, cfg, &sto, mok.conn, 6); }
